mapper.select:
select id, oper_type operType, oper_name operName, oper_role operRole, oper_status operStatus, update_time updateTime, create_time createTime from t_instructions where is_valid=1
and oper_type = #{query.operType}
and oper_name like concat('%', #{query.operName}, '%')
and create_time between #{query.startTime} and #{query.endTime}
order by create_time desc
